css:
:scope{display:block;width:100%}
.pw{--ink:#010A12;--bone:#EDE6D8;--sand:#BBAFA3;--mulberry:#5E3A3C;--clay:#8C5B46;--head:'Cormorant Garamond',serif;--body:'EB Garamond',serif;--label:'Montserrat',sans-serif;position:relative;font-family:var(--body);font-size:21px;line-height:1.5;font-weight:400;letter-spacing:0;-webkit-font-smoothing:antialiased;text-align:left;background:var(--bone);color:var(--ink)}
.pw *{box-sizing:border-box}
:where(.pw p,.pw h1,.pw h2,.pw h3){margin:0;padding:0}
:where(.pw p,.pw li,.pw h1,.pw h2,.pw h3){text-wrap:wrap}
:where(.pw h1,.pw h2,.pw h3){color:inherit}
:where(.pw){overflow-wrap:normal}
.in{max-width:1200px;margin:0 auto;padding:0 32px}
.pad{padding:160px 0}
.kick{margin:0;font-family:var(--label);font-weight:400;font-size:12px;letter-spacing:.32em;text-transform:uppercase;color:var(--mulberry)}
.rule{width:64px;height:1px;background:var(--clay);border:0;margin:28px 0 32px}
.pw h2{font-family:var(--head);font-weight:500;font-size:60px;line-height:1.08;letter-spacing:0;margin:0;text-wrap:balance;text-indent:-.0667em}
.g{display:grid;grid-template-columns:4fr 8fr;gap:64px;align-items:start}
.portrait{aspect-ratio:2/3;background:var(--sand);display:flex;align-items:center;justify-content:center;text-align:center;padding:20px;font-family:var(--label);font-size:12px;letter-spacing:.24em;text-transform:uppercase;color:var(--ink);line-height:1.5}
.portrait.has-img{padding:0;overflow:hidden;position:relative}
.portrait .os-img{position:absolute;inset:0;width:100%;height:100%;aspect-ratio:auto;padding:0;border:0;background:none}
.portrait img{width:100%;height:100%;object-fit:cover;display:block;max-width:none}
.lede{font-family:var(--head);font-style:italic;font-weight:500;font-size:30px;line-height:1.3;margin:24px 0 0}
.para{margin:22px 0 0}
.names{margin-top:40px}
.names .nl{margin:14px 0 0;color:var(--mulberry)}
.js-rv .rv{opacity:0;transform:translateY(16px);transition:opacity 1.3s ease,transform 1.3s ease}
.js-rv .rv.on{opacity:1;transform:none}
.js-rv .d1{transition-delay:.12s}
.js-rv .d2{transition-delay:.24s}
.js-rv .d3{transition-delay:.36s}
@media (max-width:767px){.pw{font-size:19px}.in{padding:0 20px}.pad{padding:88px 0}.pw h2{font-size:40px}.g{grid-template-columns:1fr;gap:32px}.portrait{max-width:240px}}
@media (prefers-reduced-motion:reduce){.js-rv .rv{opacity:1;transform:none;transition:none}}
